const ticker = String($('Tool Input').first().json.ticker || '').trim().toUpperCase();
const raw = $input.first().json || {};
const res = raw.chart && raw.chart.result && raw.chart.result[0];
if (!res) {
  return [{ json: { found: false, ticker, reason: 'No price data found. The symbol may be wrong. Non-US stocks need an exchange suffix such as .L (London), .T (Tokyo), .DE (Germany), .HK (Hong Kong).' } }];
}
const meta = res.meta || {};
const closes = ((res.indicators && res.indicators.quote && res.indicators.quote[0] && res.indicators.quote[0].close) || []).filter(v => v !== null && v !== undefined);
if (closes.length < 210) {
  return [{ json: { found: false, ticker, reason: 'Only ' + closes.length + ' trading days of history. At least about 210 are needed for a trend and risk check. Recently listed stocks are higher risk.' } }];
}
const n = closes.length;
const last = closes[n - 1];
const avg = (a) => a.reduce((s, v) => s + v, 0) / a.length;
const sma50 = avg(closes.slice(n - 50));
const sma200 = avg(closes.slice(n - 200));
const ret = (d) => (n > d ? last / closes[n - 1 - d] - 1 : null);
const r1m = ret(21), r6m = ret(126), r12m = ret(252);
const rets = [];
for (let i = n - 252; i < n; i++) { if (i > 0) rets.push(Math.log(closes[i] / closes[i - 1])); }
const m = avg(rets);
const sd = Math.sqrt(rets.reduce((s, v) => s + (v - m) * (v - m), 0) / (rets.length - 1));
const vol = sd * Math.sqrt(252);
const yr = closes.slice(Math.max(0, n - 252));
let peak = yr[0], maxDD = 0;
for (const q of yr) { if (q > peak) peak = q; const dd = q / peak - 1; if (dd < maxDD) maxDD = dd; }
const hi = Math.max.apply(null, yr), lo = Math.min.apply(null, yr);
const pos = (last - lo) / (hi - lo);
let trend = 0;
if (last > sma200) trend += 15;
if (sma50 > sma200) trend += 10;
if (last > sma50) trend += 5;
if (r6m !== null && r6m > 0) trend += 10;
let risk = 0;
risk += vol < 0.2 ? 20 : vol < 0.3 ? 14 : vol < 0.45 ? 8 : 2;
risk += maxDD > -0.15 ? 20 : maxDD > -0.25 ? 14 : maxDD > -0.4 ? 7 : 2;
const rng = pos >= 0.4 && pos <= 0.9 ? 20 : pos > 0.9 ? 12 : 8;
const score = trend + risk + rng;
const rating = score >= 75 ? 'LOWER RISK PROFILE' : score >= 55 ? 'MODERATE RISK' : 'HIGH RISK';
const r2 = (v) => (v === null ? null : Math.round(v * 10000) / 100);
const flags = [];
if (last < sma200) flags.push('Price below 200-day average (long-term downtrend)');
if (sma50 < sma200) flags.push('50-day average below 200-day average (weak trend)');
if (vol >= 0.45) flags.push('Very high volatility');
if (maxDD <= -0.4) flags.push('Fell more than 40% from its peak within the last year');
if (pos > 0.95) flags.push('At the top of its 52-week range, high pullback risk');
if (r1m !== null && r1m < -0.15) flags.push('Dropped more than 15% in the last month');
return [{ json: {
  found: true,
  symbol: meta.symbol || ticker,
  name: meta.longName || meta.shortName || ticker,
  exchange: meta.exchangeName || '',
  currency: meta.currency || '',
  price: Math.round(last * 100) / 100,
  sma50: Math.round(sma50 * 100) / 100,
  sma200: Math.round(sma200 * 100) / 100,
  high52w: Math.round(hi * 100) / 100,
  low52w: Math.round(lo * 100) / 100,
  return1mPct: r2(r1m),
  return6mPct: r2(r6m),
  return12mPct: r2(r12m),
  volatilityPct: r2(vol),
  maxDrawdown1yPct: r2(maxDD),
  rangePositionPct: r2(pos),
  trendScore: trend,
  riskScore: risk,
  rangeScore: rng,
  score,
  rating,
  redFlags: flags
} }];

const ticker = String($('Tool Input').first().json.ticker || '').trim().toUpperCase();
const want = ticker.replace('.NG', '');
const raw = $input.first().json || {};
const list = (raw.data && raw.data.data) || [];
if (!raw.success || !list.length) {
  return [{ json: { found: false, ticker, reason: 'No Nigerian Exchange (NGX) company matched ' + want + '. Ask the user for the exact NGX symbol, for example DANGCEM, DANGSUGAR, GTCO, ZENITHBANK, MTNN.' } }];
}
let c = list.find(function (x) { return String(x.symbol).toUpperCase() === want; });
if (!c) c = list[0];
const price = Number(c.price);
const hi = Number(c.high_52wk);
const lo = Number(c.low_52wk);
const m52 = Number(c.change_52w_percent);
const ytd = Number(c.change_ytd_percent);
const m1 = Number(c.change_1m_percent);
const d7 = Number(c.change_7d_percent);
const pos = hi > lo ? (price - lo) / (hi - lo) : 0.5;
const fromHigh = hi > 0 ? price / hi - 1 : 0;
const widthRatio = lo > 0 ? hi / lo : 99;
let momentum = 0;
if (m52 > 0) momentum += 15;
if (ytd > 0) momentum += 10;
if (m1 > 0) momentum += 10;
if (d7 > 0) momentum += 5;
let risk = 0;
risk += widthRatio < 1.5 ? 20 : widthRatio < 2.5 ? 12 : 4;
risk += fromHigh > -0.1 ? 20 : fromHigh > -0.25 ? 14 : fromHigh > -0.4 ? 7 : 2;
const rng = pos >= 0.4 && pos <= 0.9 ? 20 : pos > 0.9 ? 12 : 8;
const score = momentum + risk + rng;
const rating = score >= 75 ? 'LOWER RISK PROFILE' : score >= 55 ? 'MODERATE RISK' : 'HIGH RISK';
const flags = [];
if (widthRatio >= 2.5) flags.push('52-week high is more than 2.5 times the 52-week low (very large price swings)');
if (fromHigh <= -0.25) flags.push('Trading more than 25% below its 52-week high');
if (pos > 0.95) flags.push('At the top of its 52-week range, high pullback risk');
if (m1 < -10) flags.push('Dropped more than 10% in the last month');
if (ytd > 100) flags.push('Up more than 100% this year, so a pullback is possible');
const r2 = function (v) { return Math.round(v * 100) / 100; };
return [{ json: {
  found: true,
  limitedData: true,
  dataNote: 'NGX snapshot only: current price, 52-week range and 7d/1m/YTD/52w changes. No price history, so no moving averages, volatility or drawdown, and no chart. Lower confidence than other stocks.',
  symbol: c.symbol + '.NG',
  name: c.name,
  exchange: 'Nigerian Exchange (NGX)',
  currency: 'NGN',
  price: price,
  high52w: hi,
  low52w: lo,
  change7dPct: d7,
  change1mPct: m1,
  changeYtdPct: ytd,
  change52wPct: m52,
  fromHigh52wPct: r2(fromHigh * 100),
  rangePositionPct: r2(pos * 100),
  sector: c.sector,
  lastUpdated: c.last_updated,
  momentumScore: momentum,
  riskScore: risk,
  rangeScore: rng,
  score: score,
  rating: rating,
  redFlags: flags
} }];
